from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, comps = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)]); seen.add((r, c)); cells = []
            while q:
                y, x = q.popleft(); cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append((color, cells))

    def longest(groups):
        best = (0, None, None, None)
        for key, ps in groups.items():
            for p in ps:
                if p-1 not in ps:
                    n = 0
                    while p+n in ps: n += 1
                    if n > best[0]: best = (n, key, p, p+n-1)
        return best

    def lines(cells):
        rows, cols = {}, {}
        for r,c in cells:
            rows.setdefault(r,set()).add(c); cols.setdefault(c,set()).add(r)
        return longest(rows), longest(cols)

    marker_i, best = None, (-1,-1,-1)
    for i,(color,cells) in enumerate(comps):
        hl,vl=lines(cells)
        score=(min(hl[0],vl[0]),hl[0]+vl[0],len(cells))
        if hl[0]>=3 and vl[0]>=3 and score>best:
            marker_i,best=i,score
    if marker_i is None: return out
    marker_color, marker=comps[marker_i]
    hl,vl=lines(marker)
    er, ec = hl[1], vl[1]
    if er is None or ec is None or not (hl[2] <= ec <= hl[3] and vl[2] <= er <= vl[3]): return out
    # The inside quadrant lies in the direction of both bars from their elbow.
    row_dir = 1 if er == vl[2] else -1
    col_dir = 1 if ec == hl[2] else -1

    def shape(cells):
        r0=min(r for r,c in cells); c0=min(c for r,c in cells)
        return tuple(sorted((r-r0,c-c0) for r,c in cells))
    keys=[shape(cells) for _,cells in comps]
    def quadrant(cells):
        cr=sum(r for r,c in cells)/len(cells); cc=sum(c for r,c in cells)/len(cells)
        return (1 if cr>er else -1, 1 if cc>ec else -1)

    # A small exemplar lies in the L's inner quadrant. Recolor its congruent
    # copy outside that quadrant with the L's color.
    matches=[]
    for i in range(len(comps)):
        if i==marker_i or quadrant(comps[i][1])!=(row_dir,col_dir): continue
        for j in range(len(comps)):
            if j==marker_i or i==j or keys[i]!=keys[j]: continue
            if quadrant(comps[j][1])!=(row_dir,col_dir):
                matches.append((len(comps[i][1]),i,j))
    if not matches: return out
    # Use the largest exact silhouette for which an inner exemplar and outer copy exist.
    size=max(x[0] for x in matches)
    _,_,target=matches[0]
    for n,i,j in matches:
        if n==size:
            target=j
            break
    for r,c in comps[target][1]: out[r][c]=marker_color
    return out
